template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 40mm;
  height: 30mm;
  padding: 1.5mm 1.6mm 1.2mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 8.5px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
}
.price {
  font-size: 14px;
  font-weight: 800;
  margin-top: 0.8mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 8px;
  font-weight: 700;
  margin-left: 0.6mm;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4mm;
  margin-top: auto;
  width: 100%;
}
.code {
  font-size: 7.5px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.05em;
  text-align: center;
  white-space: nowrap;
}
img.barcode {
  height: 11mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
